import{_ as t,o as n,c as o,a2 as a}from"./chunks/framework.CANn83f8.js";const s="/images/features/reports-financial-pulse.png",r="/images/features/reports-surplus-allocation.png",i="/images/features/reports-money-in-motion.png",l="/images/features/reports-where-life-costs.png",p="/images/features/reports-merchant-spending.png",c="/images/features/reports-money-map.png",v=JSON.parse('{"title":"Reports","description":"","frontmatter":{},"headers":[],"relativePath":"features/reports.md","filePath":"features/reports.md","lastUpdated":1790713879000}'),h={name:"features/reports.md"};function d(g,e,m,u,f,y){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h1><p>ExpenseAutomator Reports help you understand how income, spending and retained money change over time.</p><p>Reports combine your imported transactions into a longer-term financial picture. You can compare months, identify your largest spending areas and follow how income was distributed across your expenses.</p><h2 id="report-period" tabindex="-1">Report period <a class="header-anchor" href="#report-period" aria-label="Permalink to &quot;Report period&quot;">​</a></h2><p>Use the period controls in the top right corner to choose how much history to include:</p><ul><li><strong>6M:</strong> the latest six months</li><li><strong>YTD:</strong> the current year to date</li><li><strong>1Y:</strong> the latest year</li><li><strong>2Y:</strong> the latest two years</li><li><strong>5Y:</strong> the latest five years</li><li><strong>All:</strong> all available history</li></ul><p>Free accounts can view six-month and year-to-date reports. The one-year, two-year, five-year and all-history periods require Premium.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Report totals are calculated from the transactions available in ExpenseAutomator. Import newer statements to keep reports up to date.</p></div><p>Transactions assigned to a transfer category are excluded so moving money between your own accounts does not count as income or spending.</p><h2 id="financial-pulse" tabindex="-1">Financial pulse <a class="header-anchor" href="#financial-pulse" aria-label="Permalink to &quot;Financial pulse&quot;">​</a></h2><p>The Financial pulse section summarizes the selected period.</p><p><img src="'+s+'" alt="Account details"></p><p><strong>Kept after spending</strong> is your recorded income minus recorded spending. A positive result is displayed in green and a negative result in red.</p><p>The <strong>income retained</strong> percentage shows how much of your income remained after spending. The summary also displays:</p><ul><li>Total income</li><li>Total spending</li><li>Average monthly spending</li><li>The number of months where income was greater than spending</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The amount kept after spending is not your bank balance. It reflects reportable transactions for the selected period and does not automatically include future bills or planned spending.</p></div><h2 id="surplus-allocation" tabindex="-1">Surplus allocation <a class="header-anchor" href="#surplus-allocation" aria-label="Permalink to &quot;Surplus allocation&quot;">​</a></h2><p>Surplus allocation separates money that remained after spending from money you deliberately moved into savings or investments.</p><p><img src="'+r+'" alt="Account details"></p><p>It displays:</p><ul><li><strong>Operating surplus:</strong> income minus spending</li><li><strong>Saved / invested:</strong> surplus linked to savings and investment movements</li><li><strong>Unallocated surplus:</strong> operating surplus that has not been identified as saved or invested</li></ul><p>When surplus has been allocated in more than one currency, the currency breakdown shows the amounts assigned to savings and investments.</p><p>To populate this section, link outgoing contributions to a savings or investment movement and mark them as saved surplus.</p><h2 id="money-in-motion" tabindex="-1">Money in motion <a class="header-anchor" href="#money-in-motion" aria-label="Permalink to &quot;Money in motion&quot;">​</a></h2><p>The <strong>Money in motion</strong> chart compares each month in the selected period.</p><p><img src="'+i+'" alt="Account details"></p><ul><li>Green bars represent income</li><li>Spending bars represent money spent</li><li>The line represents the net amount remaining after spending</li></ul><p>Hover over the chart to see the income, spending and net value for a particular month. Months below the zero line finished with more spending than income.</p><h2 id="where-life-costs-you" tabindex="-1">Where life costs you <a class="header-anchor" href="#where-life-costs-you" aria-label="Permalink to &quot;Where life costs you&quot;">​</a></h2><p>This section groups spending by its assigned category or budget.</p><p><img src="'+l+'" alt="Account details"></p><p>The chart and list show the six largest spending areas, including:</p><ul><li>The category or budget name</li><li>Its percentage of total reportable spending</li><li>The amount spent</li></ul><p>Hover over a section of the chart or an item in the list to focus on that spending area.</p><p>Uncategorized spending appears as <strong>Uncategorized</strong>. Assign categories or budgets to your transactions to make this section more useful.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Review uncategorized transactions before using category reports to make spending decisions.</p></div><h2 id="signals-worth-noticing" tabindex="-1">Signals worth noticing <a class="header-anchor" href="#signals-worth-noticing" aria-label="Permalink to &quot;Signals worth noticing&quot;">​</a></h2><p>ExpenseAutomator highlights three patterns from the selected period:</p><ul><li>The month that left the most money after spending</li><li>Your largest spending category</li><li>The month with the highest spending</li></ul><p>These signals provide a quick starting point for reviewing the report. Click <strong>Explore the transactions behind this report</strong> to open the Transactions page and investigate the underlying activity.</p><h2 id="merchant-spending" tabindex="-1">Merchant spending <a class="header-anchor" href="#merchant-spending" aria-label="Permalink to &quot;Merchant spending&quot;">​</a></h2><p>The <strong>Merchant spending</strong> chart ranks merchants by the total amount of money spent with them during the selected period.</p><p><img src="'+p+'" alt="Merchant spending"></p><p>Each merchant displays:</p><ul><li>Its position in the spending ranking</li><li>The merchant name and logo, when available</li><li>The number of matching transactions</li><li>The total amount spent</li></ul><p>The background bar represents the merchant&#39;s spending relative to the highest-spending merchant. This makes it easier to compare merchants even when their totals are very different.</p><p>The chart displays the top ten merchants by default. If more merchants are available, click <strong>Show all merchants</strong> to expand the complete ranking. Click <strong>Show top 10</strong> to return to the shorter view.</p><p>Only outgoing reportable transactions are included. Transactions assigned to a transfer category do not appear in the ranking.</p><h2 id="money-map" tabindex="-1">Money map <a class="header-anchor" href="#money-map" aria-label="Permalink to &quot;Money map&quot;">​</a></h2><p>The Money map follows recorded income into the areas it funded.</p><p><img src="'+c+'" alt="Account details"></p><p>Income flows into available money and then into your largest spending categories. If money remained after spending, it appears as <strong>Retained</strong>. If spending was greater than income, the map shows a <strong>Funding gap</strong>.</p><p>Spending outside the six largest categories is grouped under <strong>Other spending</strong>. Hover over the map to see the value represented by each flow.</p>',53)])])}const w=t(h,[["render",d]]);export{v as __pageData,w as default};
